import React, { useState } from 'react';
import './Gallery.css';
import LazyImage from './LazyImage';

function Gallery() {
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedImage, setSelectedImage] = useState(null);
  const assetPath = (path) => encodeURI(path);

  const galleryImages = {
    regularService: [
      {
        id: 1,
        title: 'Professional Service Center',
        category: 'regular',
        image: assetPath('/img/web images/regular services/pexels-19x14-8478233.jpg'),
        description: 'State-of-the-art service facility'
      },
      {
        id: 2,
        title: 'Expert Technicians',
        category: 'regular',
        image: assetPath('/img/web images/regular services/pexels-lynxexotics-15489246.jpg'),
        description: 'Certified technicians at work'
      },
      {
        id: 3,
        title: 'Quality Service',
        category: 'regular',
        image: assetPath('/img/web images/regular services/pexels-tami-19499386.jpg'),
        description: 'Premium vehicle maintenance'
      },
      {
        id: 4,
        title: 'Advanced Diagnostics',
        category: 'regular',
        image: assetPath('/img/web images/regular services/pexels-artempodrez-8985922.jpg'),
        description: 'Modern diagnostic equipment'
      },
      {
        id: 5,
        title: 'Complete Inspection',
        category: 'regular',
        image: assetPath('/img/web images/regular services/pexels-artempodrez-8986139.jpg'),
        description: 'Thorough vehicle inspection'
      },
      {
        id: 6,
        title: 'Professional Care',
        category: 'regular',
        image: assetPath('/img/web images/regular services/pexels-fatih-erden-141946798-10490623.jpg'),
        description: 'Expert vehicle care services'
      }
    ],
    breakdown: [
      {
        id: 7,
        title: 'Emergency Response',
        category: 'breakdown',
        image: assetPath('/img/web images/break dwon/pexels-a-q-91521018-18863497.jpg'),
        description: '24/7 emergency assistance'
      },
      {
        id: 8,
        title: 'Roadside Help',
        category: 'breakdown',
        image: assetPath('/img/web images/break dwon/pexels-edurawpro-21831855.jpg'),
        description: 'Quick roadside repairs'
      },
      {
        id: 9,
        title: 'Breakdown Recovery',
        category: 'breakdown',
        image: assetPath('/img/web images/break dwon/pexels-jonathan-reynaga-861774-17429096.jpg'),
        description: 'Professional breakdown service'
      },
      {
        id: 10,
        title: 'Rapid Assistance',
        category: 'breakdown',
        image: assetPath('/img/web images/break dwon/pexels-mikebirdy-943930.jpg'),
        description: 'Fast emergency response'
      },
      {
        id: 11,
        title: 'Towing Service',
        category: 'breakdown',
        image: assetPath('/img/web images/break dwon/pexels-mykola128-8660855.jpg'),
        description: 'Professional towing assistance'
      },
      {
        id: 12,
        title: 'On-Site Repair',
        category: 'breakdown',
        image: assetPath('/img/web images/break dwon/pexels-usuariodaniel-10061763.jpg'),
        description: 'On-the-spot emergency repairs'
      }
    ],
    modification: [
      {
        id: 13,
        title: 'Custom Performance',
        category: 'modification',
        image: assetPath('/img/web images/modificasoin/pexels-chickenbunny-102941452-14267360.jpg'),
        description: 'Performance tuning and upgrades'
      },
      {
        id: 14,
        title: 'Aesthetic Upgrades',
        category: 'modification',
        image: assetPath('/img/web images/modificasoin/pexels-dimkidama-14999240.jpg'),
        description: 'Custom body modifications'
      },
      {
        id: 15,
        title: 'Premium Customization',
        category: 'modification',
        image: assetPath('/img/web images/modificasoin/pexels-kyle-buss-45080540-7457234.jpg'),
        description: 'Exclusive custom modifications'
      },
      {
        id: 16,
        title: 'Advanced Tuning',
        category: 'modification',
        image: assetPath('/img/web images/modificasoin/pexels-bylukemiller-32725702.jpg'),
        description: 'ECU remapping and tuning'
      },
      {
        id: 17,
        title: 'Interior Customization',
        category: 'modification',
        image: assetPath('/img/web images/modificasoin/pexels-jacobmooreimages-12330674.jpg'),
        description: 'Premium interior upgrades'
      },
      {
        id: 18,
        title: 'Exterior Enhancement',
        category: 'modification',
        image: assetPath('/img/web images/modificasoin/pexels-natasha-filippovskaya-2203043-10257898.jpg'),
        description: 'Body kit and styling upgrades'
      },
      {
        id: 19,
        title: 'Full Customization',
        category: 'modification',
        image: assetPath('/img/web images/modificasoin/pexels-sam-mccool-1923523643-28762239.jpg'),
        description: 'Complete vehicle customization'
      }
    ]
  };

  const allImages = [
    ...galleryImages.regularService,
    ...galleryImages.breakdown,
    ...galleryImages.modification
  ];

  const filterImages = () => {
    if (selectedCategory === 'all') return allImages;
    return allImages.filter(img => img.category === selectedCategory);
  };

  const filteredImages = filterImages();

  return (
    <div className="gallery-page">
      <div className="gallery-header">
        <h1>AutoX Gallery</h1>
        <p>Explore our services through images</p>
      </div>

      <div className="gallery-filters">
        <button 
          className={`filter-btn ${selectedCategory === 'all' ? 'active' : ''}`}
          onClick={() => setSelectedCategory('all')}
        >
          All Services
        </button>
        <button 
          className={`filter-btn ${selectedCategory === 'regular' ? 'active' : ''}`}
          onClick={() => setSelectedCategory('regular')}
        >
          Regular Services
        </button>
        <button 
          className={`filter-btn ${selectedCategory === 'breakdown' ? 'active' : ''}`}
          onClick={() => setSelectedCategory('breakdown')}
        >
          Breakdown
        </button>
        <button 
          className={`filter-btn ${selectedCategory === 'modification' ? 'active' : ''}`}
          onClick={() => setSelectedCategory('modification')}
        >
          Modification
        </button>
      </div>

      <div className="gallery-grid">
        {filteredImages.map((image, index) => (
          <div 
            key={image.id} 
            className="gallery-item"
            onClick={() => setSelectedImage(image)}
          >
            <div className="gallery-image-wrapper">
              <LazyImage 
                src={image.image} 
                alt={image.title}
                aspectRatio="4/3"
                priority={index < 6}
                className="gallery-img"
              />
              <div className="gallery-overlay">
                <h3>{image.title}</h3>
                <p>{image.description}</p>
                <span className="view-btn">View Details</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {selectedImage && (
        <div className="lightbox" onClick={() => setSelectedImage(null)}>
          <div className="lightbox-content" onClick={(e) => e.stopPropagation()}>
            <button className="lightbox-close" onClick={() => setSelectedImage(null)}>×</button>
            <LazyImage 
              src={selectedImage.image} 
              alt={selectedImage.title}
              aspectRatio="16/9"
              priority={true}
              className="lightbox-img"
            />
            <div className="lightbox-info">
              <h2>{selectedImage.title}</h2>
              <p>{selectedImage.description}</p>
              <span className="category-badge">{selectedImage.category}</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Gallery;
